<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;
use App\Services\{HomeRemedyImportService,HomeRemedyExportService};
use App\Models\HomeRemedy;
use Illuminate\Http\Request;
class HomeRemedyImportExportController extends Controller { public function importForm(){return view('admin.nani-dadi.import');} public function import(Request $request,HomeRemedyImportService $service){$request->validate(['file'=>'required|file|mimes:csv,txt,xlsx|max:10240','mode'=>'required|in:create_only,create_update,update_only']);$result=$service->import($request->file('file')->getRealPath(),$request->mode);return back()->with('import_result',$result);} public function template(){return response()->streamDownload(function(){ $s=new HomeRemedyExportService; echo implode(',',array_map(fn($v)=>'"'.str_replace('"','""',$v).'"', $s::columns()))."\n"; },'home-remedies-import-template.csv',['Content-Type'=>'text/csv; charset=UTF-8']);} public function export(Request $request,HomeRemedyExportService $service){$q=HomeRemedy::query()->when($request->category,fn($x,$v)=>$x->where('category_id',$v))->when($request->review,fn($x,$v)=>$x->where('medical_review_status',$v))->when($request->evidence,fn($x,$v)=>$x->where('evidence_level',$v))->when($request->has('published'),fn($x)=>$x->where('is_published',$request->boolean('published')))->when($request->has('featured'),fn($x)=>$x->where('is_featured',$request->boolean('featured')));return response($service->csv($q),200,['Content-Type'=>'text/csv; charset=UTF-8','Content-Disposition'=>'attachment; filename="home-remedies.csv"']);} }
